/**
 * Friends API 集成测试
 *
 * 本文档测试完整的用户流程，包括好友请求、接受、分类等
 */

import { SynapseEnhancedClient, type IFriend } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:friends-integration");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class FriendsApiIntegrationTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;
    private createdCategoryIds: string[] = [];
    private sentRequestIds: string[] = [];

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Friends API Integration Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testCompleteFriendRequestFlow());
        results.push(await this.testCategoryManagementFlow());
        results.push(await this.testBatchOperationsFlow());
        results.push(await this.testStreamingFlow());

        await this.cleanup();

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Friends API Integration Results: ${passed}/${results.length} passed`);
    }

    private async testCompleteFriendRequestFlow(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            log.info("Testing complete friend request flow...");

            const targetUserId = `@integration-test-${Date.now()}:example.com`;

            const requestResult = await this.client.friends.sendFriendRequest({
                target_id: targetUserId,
                message: "Hello, let's be friends!",
            });

            if (requestResult.request_id) {
                this.sentRequestIds.push(requestResult.request_id);
            }

            const receivedRequests = await this.client.friends.getReceivedRequests();
            const foundRequest = receivedRequests.find((r) => r.request_id === requestResult.request_id);

            return {
                name: "Complete Friend Request Flow",
                passed: foundRequest !== undefined,
                responseTime: Date.now() - startTime,
                response: { requestId: requestResult.request_id, found: foundRequest !== undefined },
            };
        } catch (error: any) {
            return {
                name: "Complete Friend Request Flow",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testCategoryManagementFlow(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            log.info("Testing category management flow...");

            const categoryName = `Integration Test Category ${Date.now()}`;
            const createdCategory = await this.client.friends.createCategory(categoryName);

            if (createdCategory && createdCategory.id) {
                this.createdCategoryIds.push(createdCategory.id);
            }

            const categories = await this.client.friends.getCategories();
            const foundCategory = categories.find((c) => c.id === createdCategory?.id);

            let deleted = false;
            if (createdCategory?.id) {
                deleted = await this.client.friends.deleteCategory(createdCategory.id);
                const index = this.createdCategoryIds.indexOf(createdCategory.id);
                if (index > -1) {
                    this.createdCategoryIds.splice(index, 1);
                }
            }

            return {
                name: "Category Management Flow",
                passed: foundCategory !== undefined && deleted,
                responseTime: Date.now() - startTime,
                response: { created: foundCategory !== undefined, deleted },
            };
        } catch (error: any) {
            return {
                name: "Category Management Flow",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testBatchOperationsFlow(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            log.info("Testing batch operations flow...");

            const userIds = ["@test1:example.com", "@test2:example.com", "@test3:example.com"];

            const friendsMap = await this.client.friends.getFriendsBatch(userIds);

            const remarks = new Map<string, string>([
                ["@test1:example.com", "Colleague"],
                ["@test2:example.com", "Family"],
                ["@test3:example.com", "Friend"],
            ]);

            const updateResults = await this.client.friends.updateRemarksBatch(remarks);

            const successCount = Array.from(updateResults.values()).filter((r) => r).length;

            return {
                name: "Batch Operations Flow",
                passed: successCount === userIds.length,
                responseTime: Date.now() - startTime,
                response: { fetched: friendsMap.size, updated: successCount },
            };
        } catch (error: any) {
            return {
                name: "Batch Operations Flow",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testStreamingFlow(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            log.info("Testing streaming flow...");

            const friends: IFriend[] = [];
            let count = 0;

            for await (const friend of this.client.friends.streamFriends({ limit: 10 })) {
                friends.push(friend);
                count++;

                if (count >= 5) {
                    break;
                }
            }

            return {
                name: "Streaming Flow",
                passed: friends.length > 0,
                responseTime: Date.now() - startTime,
                response: { streamed: friends.length },
            };
        } catch (error: any) {
            return {
                name: "Streaming Flow",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async cleanup(): Promise<void> {
        log.info("Cleaning up test data...");

        for (const categoryId of this.createdCategoryIds) {
            try {
                await this.client.friends.deleteCategory(categoryId);
            } catch {}
        }

        this.createdCategoryIds = [];
        this.sentRequestIds = [];
    }
}

const tests = new FriendsApiIntegrationTests();
tests.runAllTests().catch((error) => log.error(error));
